import React, { useState, useEffect } from 'react';
import { ChevronRight, ChevronDown, Loader2 } from 'lucide-react';
import { parameterService } from '../../services/parameterService';
import { ratingService } from '../../services/ratingService';
import { toast } from 'react-hot-toast';
import ExpandableParameterForm from './ExpandableParameterForm';
import './ParameterListView.css';

export interface ParameterListItem {
  id: number;
  name: string;
  parameterType: string;
  description: string;
  targetValuesLocked?: boolean;
}

export interface ParameterDetails {
  parameter: {
    id: number;
    name: string;
    parameterType: string;
    description: string;
    maxValue: number;
    category: string;
  };
  allCycleYears: number[];
  cycles: CycleInfo[];
  targetValuesLocked: boolean;
  unlockedAchievedYears: number[];
  overallTarget: number | null;
  submittedValues: { [cycle: string]: SubmittedValue };
}

export interface CycleInfo {
  year: number;
  enabled: boolean;
  isTarget: boolean;
}

export interface SubmittedValue {
  actualValue?: number;
  projectedValue?: number;
  textValue?: string;
  submittedAt: string;
  isReadOnly: boolean;
}

export interface FormValues {
  actualValue?: number;
  projectedValue?: number;
  textValue?: string;
}

interface ParameterListViewProps {
  categoryName: string;
  onClose: () => void;
  onSuccess?: () => void;
}

interface ExpandedParameterState {
  [parameterId: number]: ParameterDetails;
}

const ParameterListView: React.FC<ParameterListViewProps> = ({
  categoryName,
  onClose,
  onSuccess
}) => {
  const [parameters, setParameters] = useState<ParameterListItem[]>([]);
  const [expandedParameters, setExpandedParameters] = useState<ExpandedParameterState>({});
  const [expandedParameterIds, setExpandedParameterIds] = useState<Set<number>>(new Set());
  const [isLoading, setIsLoading] = useState(true);
  const [loadingStates, setLoadingStates] = useState<{ [parameterId: number]: boolean }>({});
  const [submissionStates, setSubmissionStates] = useState<{ [parameterId: number]: boolean }>({});

  useEffect(() => {
    loadParameterList();
  }, [categoryName]);

  const loadParameterList = async () => {
    setIsLoading(true);
    try {
      console.log(`📋 Loading parameter list for category: ${categoryName}`);
      const response = await parameterService.getParameterListByCategory(categoryName);

      if (response.Status && response.Data) {
        setParameters(response.Data);
        console.log(`✅ Loaded ${response.Data.length} parameters`);
      } else {
        toast.error(response.Message || 'Failed to load parameters');
      }
    } catch (error: any) {
      console.error('Error loading parameter list:', error);
      toast.error(error.message || 'Failed to load parameters');
    } finally {
      setIsLoading(false);
    }
  };

  const handleParameterExpand = async (parameterId: number) => {
    // If already expanded, collapse it
    if (expandedParameterIds.has(parameterId)) {
      setExpandedParameterIds(prev => {
        const newSet = new Set(prev);
        newSet.delete(parameterId);
        return newSet;
      });
      return;
    }

    // Expand parameter - load details if not already loaded
    if (!expandedParameters[parameterId]) {
      setLoadingStates(prev => ({ ...prev, [parameterId]: true }));

      try {
        console.log(`📊 Loading details for parameter ${parameterId}`);
        const response = await parameterService.getParameterDetails(parameterId);

        if (response.Status && response.Data) {
          setExpandedParameters(prev => ({
            ...prev,
            [parameterId]: response.Data
          }));
          console.log(`✅ Loaded details for parameter ${parameterId}`);
        } else {
          toast.error(response.Message || 'Failed to load parameter details');
          return;
        }
      } catch (error: any) {
        console.error(`Error loading parameter details for ${parameterId}:`, error);
        toast.error(error.message || 'Failed to load parameter details');
        return;
      } finally {
        setLoadingStates(prev => ({ ...prev, [parameterId]: false }));
      }
    }

    // Expand the parameter
    setExpandedParameterIds(prev => new Set(prev).add(parameterId));
  };

  const refreshParameterDetails = async (parameterId: number) => {
    const detailsResponse = await parameterService.getParameterDetails(parameterId);
    if (detailsResponse.Status && detailsResponse.Data) {
      setExpandedParameters(prev => ({
        ...prev,
        [parameterId]: detailsResponse.Data
      }));
    }
  };

  const handleTargetSubmit = async (
    parameterId: number,
    targetValues: { year: number; value: number | string }[],
    overallTarget: number | null
  ): Promise<boolean> => {
    setSubmissionStates(prev => ({ ...prev, [parameterId]: true }));

    try {
      const response = await ratingService.submitTargetValues(parameterId, targetValues, overallTarget);

      if (response.Status) {
        toast.success('Target values submitted and locked successfully!');
        await refreshParameterDetails(parameterId);
        if (onSuccess) onSuccess();
        return true;
      } else {
        toast.error(response.Message || 'Failed to submit target values');
        return false;
      }
    } catch (error: any) {
      console.error(`Error submitting targets for parameter ${parameterId}:`, error);
      toast.error(error.message || 'Failed to submit target values');
      return false;
    } finally {
      setSubmissionStates(prev => ({ ...prev, [parameterId]: false }));
    }
  };

  const handleParameterSubmit = async (
    parameterId: number,
    cycle: number,
    values: FormValues
  ): Promise<boolean> => {
    setSubmissionStates(prev => ({ ...prev, [parameterId]: true }));

    try {
      const response = await ratingService.submitIndividualParameter(parameterId, cycle, values);

      if (response.Status) {
        await refreshParameterDetails(parameterId);
        if (onSuccess) onSuccess();
        return true;
      } else {
        toast.error(response.Message || 'Failed to submit parameter');
        return false;
      }
    } catch (error: any) {
      console.error(`Error submitting parameter ${parameterId}:`, error);
      toast.error(error.message || 'Failed to submit parameter');
      return false;
    } finally {
      setSubmissionStates(prev => ({ ...prev, [parameterId]: false }));
    }
  };

  const getParameterTypeColor = (type: string): string => {
    switch (type) {
      case 'Numeric': return '#3498db';
      case 'Text': return '#27ae60';
      case 'Percentage': return '#e67e22';
      case 'Boolean': return '#9b59b6';
      default: return '#6c757d';
    }
  };

  if (isLoading) {
    return (
      <div className="parameter-list-loading">
        <Loader2 className="animate-spin" size={24} />
        <p>Loading parameters...</p>
      </div>
    );
  }

  if (parameters.length === 0) {
    return (
      <div className="parameter-list-empty">
        <p>No parameters found for this category.</p>
      </div>
    );
  }

  return (
    <div className="parameter-list-view">
      <div className="parameter-list-header">
        <h3>{categoryName}</h3>
        <p>{parameters.length} parameters available</p>
      </div>

      <div className="parameter-list-container">
        {parameters.map((parameter) => {
          const isExpanded = expandedParameterIds.has(parameter.id);
          const isLoadingDetails = loadingStates[parameter.id] || false;
          const isSubmitting = submissionStates[parameter.id] || false;
          const parameterDetails = expandedParameters[parameter.id];

          return (
            <div
              key={parameter.id}
              className={`parameter-list-item ${isExpanded ? 'expanded' : ''}`}
            >
              {/* Parameter Summary - Always Visible */}
              <div
                className="parameter-summary"
                onClick={() => handleParameterExpand(parameter.id)}
              >
                <div className="parameter-info">
                  <div className="parameter-header">
                    <h4 className="parameter-name">{parameter.name}</h4>
                    <span
                      className="parameter-type-badge"
                      style={{ backgroundColor: getParameterTypeColor(parameter.parameterType) }}
                    >
                      {parameter.parameterType}
                    </span>
                    {(() => {
                      const locked = parameterDetails
                        ? parameterDetails.targetValuesLocked
                        : parameter.targetValuesLocked;
                      if (locked === undefined) return null;
                      return (
                        <span className={`target-status-badge ${locked ? 'target-done' : 'target-pending'}`}>
                          {locked ? 'Targets: Done' : 'Targets: Pending'}
                        </span>
                      );
                    })()}
                  </div>
                  {parameter.description && (
                    <p className="parameter-description">{parameter.description}</p>
                  )}
                </div>

                <div className="parameter-expand-icon">
                  {isLoadingDetails ? (
                    <Loader2 className="animate-spin" size={16} />
                  ) : (
                    <>
                      {isExpanded ? (
                        <ChevronDown size={16} />
                      ) : (
                        <ChevronRight size={16} />
                      )}
                    </>
                  )}
                </div>
              </div>

              {/* Expandable Form - Conditionally Visible */}
              {isExpanded && parameterDetails && (
                <ExpandableParameterForm
                  parameterDetails={parameterDetails}
                  onSubmit={handleParameterSubmit}
                  onSubmitTargets={handleTargetSubmit}
                  onCollapse={() => handleParameterExpand(parameter.id)}
                  isSubmitting={isSubmitting}
                />
              )}
            </div>
          );
        })}
      </div>

      <div className="parameter-list-footer">
        <button
          type="button"
          className="btn btn-secondary"
          onClick={onClose}
        >
          Close
        </button>
      </div>
    </div>
  );
};

export default ParameterListView;