import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/';

const axiosInstance = axios.create({
  baseURL: API_BASE_URL,
  headers: { 'Content-Type': 'application/json' },
});

axiosInstance.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

axiosInstance.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('userRole');
      window.location.href = '/';
    }
    return Promise.reject(error);
  }
);

export interface EditRequest {
  _id: string;
  parameterId: number;
  userId: string;
  reason: string;
  requestType: 'target' | 'achieved';
  year?: number | null;
  status: 'pending' | 'approved' | 'rejected';
  createdAt: string;
  resolvedAt?: string;
  // enriched fields (admin view)
  userName?: string;
  userEmail?: string;
  parameterName?: string;
}

const editRequestService = {
  // Submit a target or achieved edit request
  async submitRequest(parameterId: number, reason: string, requestType: 'target' | 'achieved', year?: number): Promise<void> {
    try {
      const res = await axiosInstance.post('/api/target-edit-requests', { parameterId, reason, requestType, year });
      if (!res.data.Status) throw new Error(res.data.Message);
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || error.message || 'Failed to submit request');
    }
  },

  // Get all requests for a parameter (for the current user)
  async getMyRequests(parameterId: number): Promise<EditRequest[]> {
    try {
      const res = await axiosInstance.get(`/api/target-edit-requests/my?parameterId=${parameterId}`);
      return res.data.Data || [];
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to fetch request status');
    }
  },

  async getAllRequests(): Promise<EditRequest[]> {
    try {
      const res = await axiosInstance.get('/api/target-edit-requests');
      return res.data.Data || [];
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to fetch requests');
    }
  },

  async approveRequest(id: string): Promise<void> {
    try {
      const res = await axiosInstance.put(`/api/target-edit-requests/${id}/approve`);
      if (!res.data.Status) throw new Error(res.data.Message);
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to approve request');
    }
  },

  async rejectRequest(id: string): Promise<void> {
    try {
      const res = await axiosInstance.put(`/api/target-edit-requests/${id}/reject`);
      if (!res.data.Status) throw new Error(res.data.Message);
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to reject request');
    }
  }
};

export default editRequestService;
