import React, { useState, useEffect } from 'react';
import { Calendar } from 'lucide-react';
import { Button } from '../ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../ui/dialog';
import { Badge } from '../ui/badge';
import { Cycle } from '../../types/cycle.types';
import { cycleService } from '../../services/cycleService';
import { toast } from '../../hooks/use-toast';

interface YearActivationModalProps {
  isOpen: boolean;
  onClose: () => void;
  cycle: Cycle;
  onActivate: () => void;
}

export const YearActivationModal: React.FC<YearActivationModalProps> = ({
  isOpen,
  onClose,
  cycle,
  onActivate
}) => {
  const [activeYears, setActiveYears] = useState<Set<number>>(new Set());
  const [targetYearProjections, setTargetYearProjections] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (isOpen && cycle) {
      // Initialize with currently active years from activatedYears array
      const currentlyActive = new Set<number>();

      if (cycle.activatedYears) {
        cycle.activatedYears.forEach(year => {
          currentlyActive.add(year);
        });
      }

      // Check target year projection settings
      if (cycle.targetYear) {
        // If we have yearActivation data, use it
        if (cycle.yearActivation?.[cycle.targetYear]) {
          setTargetYearProjections(cycle.yearActivation[cycle.targetYear].projectionSubmissionsEnabled || false);
        } else {
          // Fallback: check if target year projections are enabled via targetYearSettings
          setTargetYearProjections(cycle.targetYearSettings?.hasProjectedSubmission || false);
        }
      }

      setActiveYears(currentlyActive);
    }
  }, [isOpen, cycle]);


  const toggleYear = (year: number) => {
    const newActiveYears = new Set(activeYears);
    if (newActiveYears.has(year)) {
      newActiveYears.delete(year);
    } else {
      newActiveYears.add(year);
    }
    setActiveYears(newActiveYears);
  };

  const handleSaveChanges = async () => {
    setSubmitting(true);
    try {
      // Convert Set to Array for the API call
      const yearsToActivate = Array.from(activeYears);

      console.log('📤 Activating years (actual values):', yearsToActivate);
      console.log('🎯 Target year projections (separate):', targetYearProjections);

      // Use batch activation API
      // Note: Target year and activated years are independent!
      // - activatedYears: years where users can submit ACTUAL values
      // - targetYearProjections: enable PROJECTED values for target year
      await cycleService.batchActivateYears(cycle._id, {
        years: yearsToActivate,
        targetYearProjections,
        reason: "Year activation updated via admin interface"
      });

      toast({
        title: "Success",
        description: "Year activations updated successfully"
      });

      onActivate();
      onClose();
    } catch (error) {
      console.error('Error updating year activations:', error);
      toast({
        title: "Error",
        description: "Failed to update year activations",
        variant: "destructive"
      });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Calendar className="h-5 w-5" />
            Year Activation - {cycle.cycleName}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6">
          {/* Cycle Overview */}
          <div className="bg-blue-50 p-4 rounded-lg">
            <h3 className="font-medium text-blue-900 mb-2">Cycle Overview</h3>
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div>
                <span className="text-blue-700">Year Range:</span>
                <span className="ml-2 font-medium">{cycle.yearRange}</span>
              </div>
              <div>
                <span className="text-blue-700">Current Active Year:</span>
                <span className="ml-2 font-medium">
                  {cycle.currentActiveYear ? (
                    <Badge variant="success">{cycle.currentActiveYear}</Badge>
                  ) : (
                    <span className="text-gray-500">None</span>
                  )}
                </span>
              </div>
              <div>
                <span className="text-blue-700">Target Year:</span>
                <span className="ml-2 font-medium">
                  {cycle.targetYear ? (
                    <Badge variant="outline">{cycle.targetYear}</Badge>
                  ) : (
                    <span className="text-gray-500">Not set</span>
                  )}
                </span>
              </div>
              <div>
                <span className="text-blue-700">Total Years:</span>
                <span className="ml-2 font-medium">{cycle.cycleYears.length}</span>
              </div>
            </div>
          </div>

          {/* Year Selection */}
          <div className="space-y-4">
            <h3 className="text-lg font-medium">Available Years</h3>

            <div className="grid grid-cols-4 gap-3">
              {cycle.cycleYears.map((year) => {
                const isActive = activeYears.has(year);
                const isTargetYear = year === cycle.targetYear;

                return (
                  <div
                    key={year}
                    className={`
                      p-3 border rounded-lg cursor-pointer transition-all relative
                      ${isActive ? 'border-green-500 bg-green-50' : 'border-gray-200 hover:border-blue-300'}
                      ${isTargetYear ? 'border-purple-300 bg-purple-50' : ''}
                    `}
                    onClick={() => toggleYear(year)}
                  >
                    <div className="text-center">
                      <div className="text-lg font-medium">{year}</div>
                      <Badge
                        variant={isActive ? 'success' : 'secondary'}
                        className={`text-xs mt-1 ${isActive ? 'bg-green-100 text-green-800' : ''}`}
                      >
                        {isActive ? 'Activated' : 'Not Activated'}
                      </Badge>
                      {isTargetYear && (
                        <div className="absolute -top-2 -right-2">
                          <Badge variant="secondary" className="text-xs bg-purple-600 text-white">
                            Target
                          </Badge>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}

              {/* Target Year Projected Values Box */}
              {cycle.targetYear && (
                <div
                  className={`
                    p-3 border-2 border-dashed rounded-lg cursor-pointer transition-all
                    ${targetYearProjections
                      ? 'border-blue-400 bg-blue-50'
                      : 'border-blue-300 bg-blue-25 hover:border-blue-400'
                    }
                  `}
                  onClick={() => setTargetYearProjections(!targetYearProjections)}
                >
                  <div className="text-center">
                    <div className="text-sm font-medium text-blue-800">Target Year</div>
                    <div className="text-lg font-bold text-blue-900">{cycle.targetYear}</div>
                    <Badge
                      variant={targetYearProjections ? 'success' : 'outline'}
                      className={`text-xs mt-1 ${
                        targetYearProjections
                          ? 'bg-blue-100 text-blue-800'
                          : 'border-blue-400 text-blue-700'
                      }`}
                    >
                      {targetYearProjections ? 'Target Values ON' : 'Target Values'}
                    </Badge>
                  </div>
                </div>
              )}
            </div>

          </div>

          {/* Actions */}
          <div className="flex justify-end space-x-3 pt-4 border-t">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={submitting}
            >
              Cancel
            </Button>
            <Button
              onClick={handleSaveChanges}
              disabled={submitting}
              className="min-w-[120px]"
            >
              {submitting ? 'Saving...' : 'Save Changes'}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default YearActivationModal;