import React, { useState, useEffect } from 'react';
import { BarChart3 } from 'lucide-react';
import { Cycle } from '../../../types/cycle.types';
import { cycleService } from '../../../services/cycleService';
import { toast } from 'react-hot-toast';
import { CreateCycleModal } from '../../../components/cycle-modals/CreateCycleModal';
import { CycleDetailsModal } from '../../../components/cycle-modals/CycleDetailsModal';
import { YearActivationModal } from '../../../components/cycle-modals/YearActivationModal';
import './CycleManagement.css';

export const CycleManagement: React.FC = () => {
  const [cycles, setCycles] = useState<Cycle[]>([]);
  const [activeCycle, setActiveCycle] = useState<Cycle | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedCycle, setSelectedCycle] = useState<Cycle | null>(null);

  // Modal states
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [showYearActivationModal, setShowYearActivationModal] = useState(false);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [totalCycles, setTotalCycles] = useState(0);
  const itemsPerPage = 10;

  useEffect(() => {
    loadCycles();
    loadActiveCycle();
  }, [currentPage]);

  const loadCycles = async () => {
    try {
      setLoading(true);
      const response = await cycleService.getAllCycles({
        page: currentPage,
        limit: itemsPerPage,
        sortBy: 'createdAt',
        sortOrder: 'desc'
      });
      setCycles(response.data.cycles);
      setTotalCycles(response.data.pagination.totalItems || response.data.cycles.length);
    } catch (error) {
      toast.error('Failed to load cycles');
    } finally {
      setLoading(false);
    }
  };

  const loadActiveCycle = async () => {
    try {
      const active = await cycleService.getActiveCycle(true);
      setActiveCycle(active);
    } catch (error) {
      console.error('Error loading active cycle:', error);
    }
  };

  const handleCreateCycle = async (cycleData: any) => {
    await cycleService.createCycle(cycleData);
    toast.success('Cycle created successfully');
    setShowCreateModal(false);
    loadCycles();
  };

  const handleActivateCycle = async (cycleId: number) => {
    try {
      await cycleService.updateCycle(cycleId, { isActive: true });
      toast.success('Cycle activated successfully');
      loadCycles();
      loadActiveCycle();
    } catch {
      toast.error('Failed to activate cycle');
    }
  };

  const handleDeactivateCycle = async (cycleId: number) => {
    try {
      await cycleService.updateCycle(cycleId, { isActive: false });
      toast.success('Cycle deactivated successfully');
      loadCycles();
      loadActiveCycle();
    } catch {
      toast.error('Failed to deactivate cycle');
    }
  };

  const handleArchiveCycle = async (cycleId: number) => {
    if (!window.confirm('Archive this cycle?')) return;
    try {
      await cycleService.archiveCycle(cycleId, 'Archived by admin');
      toast.success('Cycle archived successfully');
      loadCycles();
      loadActiveCycle();
    } catch {
      toast.error('Failed to archive cycle');
    }
  };

  const handleDeleteCycle = async (cycleId: number) => {
    if (!window.confirm('Delete this cycle? This cannot be undone.')) return;
    try {
      await cycleService.deleteCycle(cycleId, 'Deleted by admin');
      toast.success('Cycle deleted successfully');
      loadCycles();
      loadActiveCycle();
    } catch {
      toast.error('Failed to delete cycle');
    }
  };

  const getStatusBadge = (cycle: Cycle) => {
    if (cycle.isActive) return <span className="cycle-status-badge status-active">Active</span>;
    switch (cycle.status) {
      case 'draft': return <span className="cycle-status-badge status-draft">Draft</span>;
      case 'completed': return <span className="cycle-status-badge status-completed">Completed</span>;
      case 'archived': return <span className="cycle-status-badge status-archived">Archived</span>;
      default: return <span className="cycle-status-badge status-draft">Unknown</span>;
    }
  };

  const formatYearRange = (cycle: Cycle) =>
    cycle.yearRange || `${new Date(cycle.startYear).getFullYear()}-${new Date(cycle.endYear).getFullYear()}`;

  const totalPages = Math.ceil(totalCycles / itemsPerPage);

  return (
    <div className="cycle-management-page">
      {/* Page Header */}
      <div className="page-header-row">
        <div>
          <h2>Cycle Management</h2>
          <p className="page-subtitle">Manage dynamic strategic planning cycles</p>
        </div>
        <button className="p-button p-component p-button-primary create-btn" onClick={() => setShowCreateModal(true)}>
          + Create New Cycle
        </button>
      </div>

      {/* Active Cycle Banner */}
      {activeCycle && (
        <div className="active-cycle-banner">
          <BarChart3 size={16} />
          <span>Active Cycle: <strong>{activeCycle.cycleName}</strong></span>
        </div>
      )}

      {/* Table */}
      <div className="p-datatable p-component">
        <div className="p-datatable-wrapper">
          <table className="p-datatable-table">
            <thead className="p-datatable-thead">
              <tr>
                <th style={{ width: '5%', textAlign: 'center' }}>S. No.</th>
                <th style={{ width: '30%', textAlign: 'center' }}>Cycle Name</th>
                <th style={{ width: '10%', textAlign: 'center' }}>Status</th>
                <th style={{ width: '55%', textAlign: 'left' }}>Actions</th>
              </tr>
            </thead>
            <tbody className="p-datatable-tbody">
              {loading ? (
                <tr>
                  <td colSpan={4} style={{ textAlign: 'center', padding: '2rem' }}>
                    <div className="spinner"><div className="loading-spinner"></div></div>
                  </td>
                </tr>
              ) : cycles.length === 0 ? (
                <tr>
                  <td colSpan={4} style={{ textAlign: 'center', padding: '2rem', color: '#6c757d' }}>
                    No cycles found.
                  </td>
                </tr>
              ) : (
                cycles.map((cycle, index) => (
                  <tr key={cycle._id}>
                    <td style={{ textAlign: 'center' }}>{(currentPage - 1) * itemsPerPage + index + 1}</td>
                    <td>
                      <div className="cycle-name-cell">
                        <span className="cycle-name">{cycle.cycleName || cycle.name}</span>
                        <span className="cycle-year-range">{formatYearRange(cycle)}</span>
                      </div>
                    </td>
                    <td style={{ textAlign: 'center' }}>{getStatusBadge(cycle)}</td>
                    <td>
                      <div className="action-buttons">
                        <button
                          className="action-btn edit-btn"
                          onClick={() => { setSelectedCycle(cycle); setShowDetailsModal(true); }}
                        >
                          Edit
                        </button>
                        {cycle.isActive && (
                          <button
                            className="action-btn years-btn"
                            onClick={() => { setSelectedCycle(cycle); setShowYearActivationModal(true); }}
                          >
                            Manage Years
                          </button>
                        )}
                        {!cycle.isActive && cycle.status === 'draft' && (
                          <button
                            className="action-btn activate-btn"
                            onClick={() => handleActivateCycle(cycle._id)}
                          >
                            Activate
                          </button>
                        )}
                        {cycle.isActive && (
                          <button
                            className="action-btn deactivate-btn"
                            onClick={() => handleDeactivateCycle(cycle._id)}
                          >
                            Deactivate
                          </button>
                        )}
                        {cycle.status !== 'archived' && (
                          <button
                            className="action-btn archive-btn"
                            onClick={() => handleArchiveCycle(cycle._id)}
                          >
                            Archive
                          </button>
                        )}
                        <button
                          className="action-btn delete-btn"
                          onClick={() => handleDeleteCycle(cycle._id)}
                        >
                          Delete
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Pagination */}
      <div className="p-paginator p-component p-paginator-bottom">
        <span className="p-paginator-current">
          Showing {totalCycles} of {totalCycles}
        </span>
        <div className="p-paginator-pages">
          <button
            className="p-paginator-prev p-paginator-element"
            disabled={currentPage <= 1}
            onClick={() => setCurrentPage(p => p - 1)}
          >
            Previous
          </button>
          {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
            <button
              key={page}
              className={`p-paginator-page p-paginator-element ${currentPage === page ? 'p-highlight' : ''}`}
              onClick={() => setCurrentPage(page)}
            >
              {page}
            </button>
          ))}
          <button
            className="p-paginator-next p-paginator-element"
            disabled={currentPage >= totalPages}
            onClick={() => setCurrentPage(p => p + 1)}
          >
            Next
          </button>
        </div>
      </div>

      {/* Modals */}
      {showCreateModal && (
        <CreateCycleModal
          isOpen={showCreateModal}
          onClose={() => setShowCreateModal(false)}
          onSubmit={handleCreateCycle}
        />
      )}

      {showDetailsModal && selectedCycle && (
        <CycleDetailsModal
          isOpen={showDetailsModal}
          onClose={() => { setShowDetailsModal(false); setSelectedCycle(null); }}
          cycle={selectedCycle}
          onUpdate={loadCycles}
        />
      )}

      {showYearActivationModal && selectedCycle && (
        <YearActivationModal
          isOpen={showYearActivationModal}
          onClose={() => { setShowYearActivationModal(false); setSelectedCycle(null); }}
          cycle={selectedCycle}
          onActivate={loadCycles}
        />
      )}
    </div>
  );
};

export default CycleManagement;
