import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import Login from './pages/authentication/Login';
import Dashboard from './pages/dashboard/Dashboard';
import AdminLayout from './components/admin-layout/AdminLayout';
import AdminDashboard from './pages/admin/AdminDashboard';
import Categories from './pages/admin/categories/Categories';
import Faculties from './pages/admin/faculties/Faculties';
import Departments from './pages/admin/departments/Departments';
import Users from './pages/admin/users/Users';
import Parameters from './pages/admin/parameters/Parameters';
import CycleManagement from './pages/admin/cycles/CycleManagement';
import RatingsReport from './pages/admin/ratings-report/RatingsReportNew';
import EditRequests from './pages/admin/edit-requests/EditRequests';
import ProtectedRoute from './components/ProtectedRoute';
import './App.css';

const App: React.FC = () => {
  return (
    <Router>
      <div className="App">
        <Toaster 
          position="top-right"
          toastOptions={{
            duration: 4000,
            style: {
              background: '#363636',
              color: '#fff',
            },
          }}
        />
        
        <Routes>
          {/* Public Routes */}
          <Route path="/" element={<Login />} />
          
          {/* Protected Routes */}
          <Route 
            path="/dashboard" 
            element={
              <ProtectedRoute>
                <Dashboard />
              </ProtectedRoute>
            } 
          />
          
          {/* Admin Routes - Matching Angular structure */}
          <Route 
            path="/admin" 
            element={
              <ProtectedRoute>
                <AdminLayout />
              </ProtectedRoute>
            }
          >
            <Route index element={<AdminDashboard />} />
            <Route path="categories" element={<Categories />} />
            <Route path="faculties" element={<Faculties />} />
            <Route path="departments" element={<Departments />} />
            <Route path="user" element={<Users />} />
            <Route path="parameters" element={<Parameters />} />
            <Route path="cycles" element={<CycleManagement />} />
            <Route path="ratings-report" element={<RatingsReport />} />
            <Route path="edit-requests" element={<EditRequests />} />
          </Route>
          
          {/* Fallback */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </Router>
  );
};

export default App;
