import React, { useState, useEffect } from 'react';
import { userService } from '../../../services/userService';
import { departmentService } from '../../../services/departmentService';
import { facultyService } from '../../../services/facultyService';
import { User, Faculty, Department } from '../../../types';
import { toast } from 'react-hot-toast';
import UserModal from '../../../components/user-modal/UserModal';
import './Users.css';

const HIDDEN_USERNAMES = new Set([
  'testUser', 'test_one', 'TEST', 'new_test', 'ABC', 'test_new_updated',
  'Mubashir', 'Test3', 'ABC_TEST', 'testadmin'
]);

const Users: React.FC = () => {
  // State matching Angular component exactly
  const [pageSize] = useState<number>(100);
  const [page, setPage] = useState<number>(1);
  const [search] = useState<string>('');
  const [users, setUsers] = useState<User[]>([]);
  const [faculties, setFaculties] = useState<Faculty[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [first, setFirst] = useState<number>(0);
  const [rows] = useState<number>(10);
  const [totalRecords, setTotalRecords] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isLoadingArr, setIsLoadingArr] = useState<{ [id: string]: boolean }>({});
  const [showModal, setShowModal] = useState<boolean>(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);

  // Role definitions matching Angular implementation - Admin role filtered out for user creation
  const userRoles = ['Chairman', 'PVC', 'VC', 'Dean'].filter(role => role.toLowerCase() !== 'admin');

  useEffect(() => {
    loadInitialData();
  }, []);

  const loadInitialData = async () => {
    await Promise.all([
      getAllUsers(),
      loadFaculties(),
      loadDepartments()
    ]);
  };

  const getAllUsers = async () => {
    setIsLoading(true);
    try {
      const parameters = {
        page,
        pageSize,
        search,
      };
      
      const response = await userService.getUsers(parameters.page, parameters.pageSize, parameters.search);
      const filtered = (response.Data || []).filter((u: any) => !HIDDEN_USERNAMES.has(u.userName));
      setUsers(filtered);
      setTotalRecords(filtered.length);
    } catch (error) {
      console.error('Error loading users:', error);
      toast.error('Failed to load users');
    } finally {
      setIsLoading(false);
    }
  };

  const loadFaculties = async () => {
    try {
      const response = await facultyService.getAllFaculties();
      setFaculties(response.Data || []);
    } catch (error) {
      console.error('Error loading faculties:', error);
      toast.error('Failed to load faculties');
    }
  };

  const loadDepartments = async () => {
    try {
      const response = await departmentService.getDepartments(1, 200); // Get all departments
      setDepartments(response.Data || []);
    } catch (error) {
      console.error('Error loading departments:', error);
      toast.error('Failed to load departments');
    }
  };

  const getFacultyName = (facultyId?: string | number): string => {
    if (!facultyId) return '-';
    const facultyIdStr = facultyId.toString();
    const faculty = faculties.find(f => 
      f.id === facultyIdStr || 
      (f._id && f._id.toString() === facultyIdStr) ||
      f.id === facultyId ||
      (f._id && f._id === facultyId)
    );
    return faculty ? faculty.name : '-';
  };

  const getDepartmentName = (deptId?: string | number): string => {
    if (!deptId) return '-';
    const deptIdStr = deptId.toString();
    const department = departments.find(d => 
      d.id === deptIdStr || 
      (d._id && d._id.toString() === deptIdStr) ||
      d.id === deptId ||
      (d._id && d._id === deptId)
    );
    return department ? (department.deptName || department.name) : '-';
  };

  const getRoleColor = (role: string): string => {
    switch (role) {
      case 'Admin': return '#e74c3c';
      case 'Dean': return '#9b59b6';
      case 'Chairman': return '#3498db';
      case 'VC': return '#f39c12';
      case 'PVC': return '#e67e22';
      default: return '#27ae60';
    }
  };

  const editMethod = (user: User) => {
    setSelectedUser(user);
    setShowModal(true);
  };

  const deleteMethod = async (id: string) => {
    // Show confirmation dialog - exact Angular SweetAlert replication
    const confirmed = window.confirm(
      "You won't be able to revert this! This will delete all data related to this User!"
    );
    
    if (!confirmed) return;

    setIsLoadingArr(prev => ({ ...prev, [id]: true }));
    
    try {
      await userService.deleteUser(id);
      toast.success('User Deleted Successfully');
      getAllUsers();
    } catch (error) {
      toast.error('Failed to delete user');
    } finally {
      setIsLoadingArr(prev => ({ ...prev, [id]: false }));
    }
  };

  const resetPasswordMethod = async (user: User) => {
    const confirmed = window.confirm(
      `Reset password for user "${user.userName}"? A temporary password will be generated.`
    );
    
    if (!confirmed) return;

    setIsLoadingArr(prev => ({ ...prev, [`reset_${user.id}`]: true }));
    
    try {
      const tempPassword = 'TempPass123!';
      await userService.resetUserPassword(user.id, tempPassword);
      toast.success(`Password reset successfully! Temporary password: ${tempPassword}`);
    } catch (error) {
      toast.error('Failed to reset password');
    } finally {
      setIsLoadingArr(prev => ({ ...prev, [`reset_${user.id}`]: false }));
    }
  };

  const pageChange = (event: { first: number; rows: number; page: number }) => {
    setFirst(event.first);
    setPage(event.page);
    getAllUsers();
  };

  const openModal = (user: User | null = null) => {
    setSelectedUser(user);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedUser(null);
  };

  const handleSave = () => {
    // Refresh data and close modal
    getAllUsers();
    closeModal();
  };

  return (
    <div className="users-page">
      <h2>Users Management</h2>
      
      {/* PrimeNG p-table equivalent - EXACT Angular structure */}
      <div className="p-datatable p-component">
        <div className="p-datatable-wrapper">
          <table className="p-datatable-table">
            <thead className="p-datatable-thead">
              <tr>
                <th style={{ width: '5%', textAlign: 'center' }}>S. No.</th>
                <th style={{ width: '15%', textAlign: 'center' }}>Username</th>
                <th style={{ width: '15%', textAlign: 'center' }}>Full Name</th>
                <th style={{ width: '15%', textAlign: 'center' }}>Email</th>
                <th style={{ width: '10%', textAlign: 'center' }}>Role</th>
                <th style={{ width: '12%', textAlign: 'center' }}>Faculty</th>
                <th style={{ width: '12%', textAlign: 'center' }}>Department</th>
                <th style={{ width: '16%', textAlign: 'center' }}>Actions</th>
              </tr>
            </thead>
            <tbody className="p-datatable-tbody">
              {isLoading ? (
                <tr>
                  <td colSpan={8} className="text-center p-4">
                    <div className="spinner">
                      <div className="loading-spinner"></div>
                    </div>
                  </td>
                </tr>
              ) : users.length === 0 ? (
                <tr>
                  <td colSpan={8} className="text-center p-4">
                    No users found
                  </td>
                </tr>
              ) : (
                users.map((user, index) => (
                  <tr key={user.id || user._id}>
                    <td>{first + index + 1}</td>
                    <td>
                      <span className="username">{user.userName}</span>
                    </td>
                    <td>
                      <span className="full-name">
                        {`${user.firstName} ${user.lastName}`}
                      </span>
                    </td>
                    <td>
                      <span className="email">{user.email}</span>
                    </td>
                    <td>
                      <span 
                        className="user-role-badge"
                        style={{ backgroundColor: getRoleColor(user.userRole) }}
                      >
                        {user.userRole}
                      </span>
                    </td>
                    <td>
                      <span className="faculty-name">
                        {getFacultyName(user.facultyId)}
                      </span>
                    </td>
                    <td>
                      <span className="department-name">
                        {getDepartmentName(user.deptId)}
                      </span>
                    </td>
                    <td>
                      <div className="action-buttons">
                        <button
                          className="action-btn edit-btn"
                          onClick={() => editMethod(user)}
                          title="Edit User"
                        >
                          <img
                            src="/assets/icons/ic--round-edit.svg"
                            alt="edit-icon"
                          />
                        </button>
                        <button
                          className="action-btn reset-btn"
                          onClick={() => resetPasswordMethod(user)}
                          title="Reset Password"
                          disabled={isLoadingArr[`reset_${user.id}`]}
                        >
                          {isLoadingArr[`reset_${user.id}`] ? (
                            <div className="spinner">
                              <div className="loading-spinner small"></div>
                            </div>
                          ) : (
                            <span className="reset-icon">🔄</span>
                          )}
                        </button>
                        <button
                          className="action-btn delete-btn"
                          onClick={() => deleteMethod(user.id)}
                          title="Delete User"
                          disabled={isLoadingArr[user.id]}
                        >
                          {isLoadingArr[user.id] ? (
                            <div className="spinner">
                              <div className="loading-spinner small"></div>
                            </div>
                          ) : (
                            <img
                              src="/assets/icons/ep--delete-filled.svg"
                              alt="delete-icon"
                            />
                          )}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* PrimeNG p-paginator equivalent - EXACT Angular structure */}
      <div className="p-paginator p-component p-paginator-bottom">
        <span className="p-paginator-current">
          Showing {totalRecords} of {totalRecords}
        </span>
      </div>

      {/* Add Button - PrimeNG floating action button - EXACT Angular styling */}
      <button
        className="p-button p-button-rounded p-button-icon-only p-button-fab"
        onClick={() => openModal()}
        title="Add User"
      >
        <span className="pi pi-plus"></span>
      </button>

      {/* User Modal for Create/Edit */}
      <UserModal
        user={selectedUser}
        faculties={faculties}
        departments={departments}
        userRoles={userRoles}
        isVisible={showModal}
        onClose={closeModal}
        onSave={handleSave}
      />
    </div>
  );
};

export default Users;