import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown, X, Check } from 'lucide-react';
import './multi-select-dropdown.css';

export interface MultiSelectOption {
  value: string;
  label: string;
}

interface MultiSelectDropdownProps {
  options: MultiSelectOption[];
  value: string[];
  onChange: (selectedValues: string[]) => void;
  placeholder?: string;
  className?: string;
  disabled?: boolean;
  required?: boolean;
  error?: string;
}

const MultiSelectDropdown: React.FC<MultiSelectDropdownProps> = ({
  options,
  value = [],
  onChange,
  placeholder = "Select options...",
  className = "",
  disabled = false,
  required = false,
  error
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleToggle = () => {
    if (!disabled) {
      setIsOpen(!isOpen);
    }
  };

  const handleOptionClick = (optionValue: string, event: React.MouseEvent) => {
    event.stopPropagation();

    const newValue = value.includes(optionValue)
      ? value.filter(v => v !== optionValue)
      : [...value, optionValue];

    onChange(newValue);
  };

  const handleRemoveTag = (optionValue: string, event: React.MouseEvent) => {
    event.stopPropagation();
    const newValue = value.filter(v => v !== optionValue);
    onChange(newValue);
  };

  const getSelectedLabels = () => {
    return value.map(v => {
      const option = options.find(opt => opt.value === v);
      return option ? option.label : v;
    });
  };

  const getDisplayText = () => {
    if (value.length === 0) {
      return placeholder;
    }
    if (value.length === 1) {
      const option = options.find(opt => opt.value === value[0]);
      return option ? option.label : value[0];
    }
    return `${value.length} groups selected`;
  };

  return (
    <div className={`multi-select-dropdown ${className}`} ref={dropdownRef}>
      <div
        className={`p-dropdown p-component ${error ? 'p-invalid' : ''} ${disabled ? 'p-disabled' : ''}`}
        onClick={handleToggle}
      >
        <div className="p-dropdown-label-container">
          <div className="p-dropdown-label">
            {value.length > 0 && value.length <= 3 ? (
              <div className="selected-tags">
                {getSelectedLabels().map((label, index) => (
                  <span
                    key={value[index]}
                    className="selected-tag"
                    onClick={(e) => handleRemoveTag(value[index], e)}
                  >
                    {label}
                    <X className="tag-remove-icon" size={12} />
                  </span>
                ))}
              </div>
            ) : (
              <span className={value.length === 0 ? 'placeholder-text' : ''}>
                {getDisplayText()}
              </span>
            )}
          </div>
          <div className="p-dropdown-trigger">
            <ChevronDown
              className={`p-dropdown-trigger-icon ${isOpen ? 'rotated' : ''}`}
              size={16}
            />
          </div>
        </div>

        {isOpen && (
          <div className="p-dropdown-panel">
            <div className="p-dropdown-items-wrapper">
              <ul className="p-dropdown-items">
                {options.length === 0 ? (
                  <li className="p-dropdown-item p-dropdown-empty-message">
                    No options available
                  </li>
                ) : (
                  options.map((option) => (
                    <li
                      key={option.value}
                      className={`p-dropdown-item ${value.includes(option.value) ? 'p-highlight' : ''}`}
                      onClick={(e) => handleOptionClick(option.value, e)}
                    >
                      <div className="option-content">
                        <Check
                          className={`option-check ${value.includes(option.value) ? 'visible' : ''}`}
                          size={16}
                        />
                        <span className="option-label">{option.label}</span>
                      </div>
                    </li>
                  ))
                )}
              </ul>
            </div>
          </div>
        )}
      </div>

      {error && (
        <small className="p-error">{error}</small>
      )}

    </div>
  );
};

export default MultiSelectDropdown;