import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import { Cycle, CycleUpdateRequest } from '../../types/cycle.types';
import { cycleService } from '../../services/cycleService';
import { toast } from 'react-hot-toast';

interface CycleDetailsModalProps {
  isOpen: boolean;
  onClose: () => void;
  cycle: Cycle;
  onUpdate: () => void;
}

export const CycleDetailsModal: React.FC<CycleDetailsModalProps> = ({
  isOpen,
  onClose,
  cycle,
  onUpdate
}) => {
  const [formData, setFormData] = useState<CycleUpdateRequest>({
    name: cycle.name,
    cycleName: cycle.cycleName,
    description: cycle.description,
    startYear: cycle.startYear,
    endYear: cycle.endYear
  });
  const [submitting, setSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (isOpen && cycle) {
      setFormData({
        name: cycle.name,
        cycleName: cycle.cycleName,
        description: cycle.description,
        startYear: cycle.startYear,
        endYear: cycle.endYear
      });
      setErrors({});
    }
  }, [isOpen, cycle]);

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};
    if (!formData.cycleName?.trim()) newErrors.cycleName = 'Cycle name is required';
    if (!formData.startYear) newErrors.startYear = 'Start year is required';
    if (!formData.endYear) newErrors.endYear = 'End year is required';
    if (formData.startYear && formData.endYear) {
      const start = new Date(formData.startYear).getFullYear();
      const end = new Date(formData.endYear).getFullYear();
      if (end <= start) newErrors.endYear = 'End year must be after start year';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSave = async () => {
    if (!validate()) return;
    setSubmitting(true);
    try {
      await cycleService.updateCycle(cycle._id, formData);
      toast.success('Cycle updated successfully');
      onUpdate();
      onClose();
    } catch (error) {
      toast.error('Failed to update cycle');
    } finally {
      setSubmitting(false);
    }
  };

  if (!isOpen || !cycle) return null;

  return createPortal(
    <div className="modal-backdrop" onClick={onClose}>
      <div className="p-dialog p-component" onClick={(e) => e.stopPropagation()}>
        <div className="p-dialog-content">
          <div className="p-dialog-wrapper">
            {/* Header */}
            <div className="p-dialog-header">
              <span className="p-dialog-title">Edit Cycle</span>
              <div className="p-dialog-header-icons">
                <button className="p-dialog-header-icon p-dialog-header-close" type="button" onClick={onClose} disabled={submitting}>
                  <X className="h-4 w-4" />
                </button>
              </div>
            </div>

            {/* Body */}
            <div className="category-form">
              <div className="p-fluid">
                <div className="field col-12">
                  <label htmlFor="edit-cycleName" className="required-field">Cycle Name</label>
                  <input
                    id="edit-cycleName"
                    type="text"
                    value={formData.cycleName || ''}
                    onChange={(e) => { setFormData(p => ({ ...p, cycleName: e.target.value })); if (errors.cycleName) setErrors(p => ({ ...p, cycleName: '' })); }}
                    className={`p-inputtext p-component ${errors.cycleName ? 'p-invalid' : ''}`}
                    disabled={submitting}
                  />
                  {errors.cycleName && <small className="p-error">{errors.cycleName}</small>}
                </div>

                <div className="field col-12">
                  <label htmlFor="edit-description">Description</label>
                  <textarea
                    id="edit-description"
                    value={formData.description || ''}
                    onChange={(e) => setFormData(p => ({ ...p, description: e.target.value }))}
                    className="p-inputtextarea p-inputtext p-component"
                    rows={3}
                    disabled={submitting}
                  />
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                  <div className="field col-12">
                    <label htmlFor="edit-startYear" className="required-field">Start Year</label>
                    <input
                      id="edit-startYear"
                      type="date"
                      value={formData.startYear || ''}
                      onChange={(e) => { setFormData(p => ({ ...p, startYear: e.target.value })); if (errors.startYear) setErrors(p => ({ ...p, startYear: '' })); }}
                      className={`p-inputtext p-component ${errors.startYear ? 'p-invalid' : ''}`}
                      disabled={submitting}
                    />
                    {errors.startYear && <small className="p-error">{errors.startYear}</small>}
                  </div>

                  <div className="field col-12">
                    <label htmlFor="edit-endYear" className="required-field">End Year</label>
                    <input
                      id="edit-endYear"
                      type="date"
                      value={formData.endYear || ''}
                      onChange={(e) => { setFormData(p => ({ ...p, endYear: e.target.value })); if (errors.endYear) setErrors(p => ({ ...p, endYear: '' })); }}
                      className={`p-inputtext p-component ${errors.endYear ? 'p-invalid' : ''}`}
                      disabled={submitting}
                    />
                    {errors.endYear && <small className="p-error">{errors.endYear}</small>}
                  </div>
                </div>
              </div>

              {/* Footer */}
              <div className="p-dialog-footer">
                <button type="button" className="p-button p-component p-button-secondary" onClick={onClose} disabled={submitting}>
                  Cancel
                </button>
                <button type="button" className="p-button p-component p-button-primary" onClick={handleSave} disabled={submitting}>
                  {submitting ? 'Saving...' : 'Save Changes'}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
};

export default CycleDetailsModal;
