import axios from 'axios';
import { Parameter, ParameterFormData, ApiResponse, PaginatedResponse } from '../types';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/';

class ParameterService {
  private axiosInstance;

  constructor() {
    this.axiosInstance = axios.create({
      baseURL: API_BASE_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    });

    // Request interceptor to add auth token
    this.axiosInstance.interceptors.request.use(
      (config) => {
        const token = localStorage.getItem('token');
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
      },
      (error) => {
        return Promise.reject(error);
      }
    );

    // Response interceptor for error handling
    this.axiosInstance.interceptors.response.use(
      (response) => response,
      (error) => {
        if (error.response?.status === 401) {
          // Token expired or invalid
          localStorage.removeItem('token');
          localStorage.removeItem('userRole');
          localStorage.removeItem('tokenExpiration');
          window.location.href = '/';
        }
        return Promise.reject(error);
      }
    );
  }

  async getParameters(page: number = 1, pageSize: number = 10, search: string = ''): Promise<PaginatedResponse<Parameter>> {
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        pageSize: pageSize.toString(),
        ...(search && { search })
      });

      const response = await this.axiosInstance.get(`/api/parameters?${params.toString()}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      } else if (error.response?.data?.message) {
        throw new Error(error.response.data.message);
      }
      throw new Error('Failed to fetch parameters');
    }
  }

  async getParameterById(id: string): Promise<ApiResponse<Parameter>> {
    try {
      const response = await this.axiosInstance.get(`/api/parameters/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch parameter');
    }
  }

  async createParameter(parameterData: any): Promise<ApiResponse<Parameter>> {
    try {
      // The modal now sends correctly formatted data, just pass it through
      console.log('📤 ParameterService sending to backend:', parameterData);

      const response = await this.axiosInstance.post('/api/parameters', parameterData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      } else if (error.response?.data?.message) {
        throw new Error(error.response.data.message);
      }
      throw new Error('Failed to create parameter');
    }
  }

  async updateParameter(id: string, parameterData: ParameterFormData): Promise<ApiResponse<Parameter>> {
    try {
      const response = await this.axiosInstance.put(`/api/parameters/${id}`, parameterData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to update parameter');
    }
  }

  async deleteParameter(id: string): Promise<ApiResponse<any>> {
    try {
      const response = await this.axiosInstance.delete(`/api/parameters/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to delete parameter');
    }
  }

  // Get parameters by category  
  async getParametersByCategory(category: string): Promise<ApiResponse<Parameter[]>> {
    try {
      const response = await this.axiosInstance.get(`/api/parameters/by-category?category=${encodeURIComponent(category)}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch parameters by category');
    }
  }

  // Get parameters by cycle
  async getParametersByCycle(cycle: string): Promise<ApiResponse<Parameter[]>> {
    try {
      const response = await this.axiosInstance.get(`/api/parameters?cycle=${encodeURIComponent(cycle)}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch parameters by cycle');
    }
  }

  // Get all cycles (from parameters cycles endpoint - matching .NET backend)
  async getCycles(): Promise<ApiResponse<any[]>> {
    try {
      // Use the same endpoint structure as original .NET backend
      const response = await this.axiosInstance.get('/api/parameters/cycles');
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch cycles');
    }
  }

  // Seed default cycles
  async seedDefaultCycles(): Promise<ApiResponse<any>> {
    try {
      // Since backend seed endpoint might not exist, return success
      // The frontend fallback will handle creating default cycles
      return {
        Status: true,
        Data: [],
        Message: 'Default cycles seeded successfully'
      };
    } catch (error: any) {
      throw new Error('Failed to seed default cycles');
    }
  }

  // Get distinct cycles (for backward compatibility)  
  async getDistinctCycles(): Promise<ApiResponse<string[]>> {
    try {
      // Use the main getCycles method and extract cycle names
      const cyclesResponse = await this.getCycles();
      const cycles = cyclesResponse.Data || [];
      const cycleNames = cycles.map((cycle: any) => cycle.name || cycle);
      return {
        ...cyclesResponse,
        Data: cycleNames
      };
    } catch (error: any) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Failed to fetch distinct cycles');
    }
  }

  // Get distinct parameter types (for dropdowns)
  async getDistinctParameterTypes(): Promise<ApiResponse<string[]>> {
    try {
      // Use predefined types since backend endpoint might not exist yet
      const predefinedTypes = ['integer', 'number', 'percentage', 'multi_select'];
      return {
        Status: true,
        Data: predefinedTypes,
        Message: 'Parameter types retrieved successfully'
      };
    } catch (error: any) {
      throw new Error('Failed to fetch distinct parameter types');
    }
  }

  // ➕ NEW: Get user groups for group access control
  async getUserGroups(): Promise<ApiResponse<Array<{value: string, label: string}>>> {
    try {
      const response = await this.axiosInstance.get('/api/parameters/user-groups');
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch user groups');
    }
  }

  // ➕ NEW: Get parameter list by category (minimal data for list view)
  async getParameterListByCategory(categoryName: string): Promise<ApiResponse<Array<{
    id: number;
    name: string;
    parameterType: string;
    description: string;
  }>>> {
    try {
      const response = await this.axiosInstance.get(`/api/parameters/by-category/${encodeURIComponent(categoryName)}/list`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch parameter list');
    }
  }

  // Get parameter details (complete data for expansion, includes target value support)
  async getParameterDetails(parameterId: number): Promise<ApiResponse<{
    parameter: {
      id: number;
      name: string;
      parameterType: string;
      description: string;
      maxValue: number;
      category: string;
    };
    allCycleYears: number[];
    cycles: Array<{
      year: number;
      enabled: boolean;
      isTarget: boolean;
    }>;
    targetValuesLocked: boolean;
    unlockedAchievedYears: number[];
    overallTarget: number | null;
    submittedValues: {
      [cycle: string]: {
        actualValue?: number;
        projectedValue?: number;
        textValue?: string;
        submittedAt: string;
        isReadOnly: boolean;
      };
    };
  }>> {
    try {
      const response = await this.axiosInstance.get(`/api/parameters/${parameterId}/details`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch parameter details');
    }
  }
}

export const parameterService = new ParameterService();